    async listStudentAppointments(studentId, filters) {
      const student = await db.queryOne(`SELECT id FROM students WHERE id = ?`, [studentId]);
      if (!student) throw new NotFoundError("\u062F\u0627\u0646\u0634\u200C\u0622\u0645\u0648\u0632");
      const conditions = [`a_s.student_id = ?`];
      const params = [studentId];
      if (filters?.from) {
        conditions.push(`a.start_at >= ?`);
        params.push(filters.from);
      }
      if (filters?.to) {
        conditions.push(`a.start_at <= ?`);
        params.push(filters.to);
      }
      const rawLimit = filters?.limit;
      const limit = Math.min(Math.max(1, Number.isFinite(rawLimit) ? Number(rawLimit) : 100), 200);
      const rows = await db.query(
        `SELECT a.id AS appointment_id, a.staff_id, s.full_name AS staff_name,
                a.start_at, a.end_at, a.status, a_s.attendance AS my_attendance, a.note
           FROM appointment_students a_s
           JOIN appointments a ON a.id = a_s.appointment_id
           LEFT JOIN staff s ON s.id = a.staff_id
          WHERE ${conditions.join(" AND ")}
          ORDER BY a.start_at DESC
          LIMIT ${limit}`,
        params
      );
      return rows.map((r) => ({
        appointmentId: r.appointment_id,
        staffId: r.staff_id,
        staffName: r.staff_name,
        startAt: r.start_at,
        endAt: r.end_at,
        status: r.status,
        myAttendance: r.my_attendance,
        note: r.note
      }));
    },
