    async suggestTypesForStudent(studentId) {
      const [tagRows, typeRows] = await Promise.all([
        db.query(
          `SELECT t.id, t.name
             FROM student_tags st
             JOIN tags t ON t.id = st.tag_id
            WHERE st.student_id = ? AND t.active = 1`,
          [studentId]
        ),
        db.query(
          `SELECT * FROM case_event_types
            WHERE deleted_at IS NULL AND active = 1
              AND category = 'checklist'
            ORDER BY created_at`
        )
      ]);
      const studentTagIds = new Set(tagRows.map((r) => r.id));
      const tagNames = new Map(tagRows.map((r) => [r.id, r.name]));
      const items = typeRows.map((row) => {
        const type = typeRowToRecord(row);
        const matched = type.tags.filter((id) => studentTagIds.has(id)).map((id) => ({ id, name: tagNames.get(id) ?? "" })).filter((m) => m.name.length > 0);
        return { type, matched, score: matched.length };
      });
      const audienceRank = { both: 0, family: 1, teacher: 2 };
      items.sort(
        (a, b) => b.score - a.score || (audienceRank[a.type.audience] ?? 3) - (audienceRank[b.type.audience] ?? 3) || a.type.title.localeCompare(b.type.title, "fa")
      );
      return items;
    },
