    referralFa: ["\u062A\u0635\u0645\u06CC\u0645 \u062F\u0627\u0631\u0648\u062F\u0631\u0645\u0627\u0646\u06CC \u0641\u0642\u0637 \u0628\u0627 \u067E\u0632\u0634\u06A9", "\u062F\u0631 \u0635\u0648\u0631\u062A \u0634\u06A9 \u0631\u0634\u062F \u062D\u0633\u06CC/\u0634\u0646\u0648\u0627\u06CC\u06CC: \u0627\u0631\u062C\u0627\u0639 \u0645\u062A\u062E\u0635\u0635 \u0645\u0631\u0628\u0648\u0637"]
