      { id: "autism.c", group: "C", textFa: "\u0646\u0634\u0627\u0646\u0647\u200C\u0647\u0627 \u0627\u0632 \u062F\u0648\u0631\u0647\u0654 \u0627\u0628\u062A\u062F\u0627\u06CC\u06CC \u0631\u0634\u062F \u0648\u062C\u0648\u062F \u062F\u0627\u0634\u062A\u0647 (\u062D\u062A\u06CC \u0627\u06AF\u0631 \u06A9\u0627\u0645\u0644 \u062A\u0627 \u0645\u0637\u0627\u0644\u0628\u0647\u0654 \u0627\u062C\u062A\u0645\u0627\u0639\u06CC \u0622\u0634\u06A9\u0627\u0631 \u0646\u0634\u062F\u0647 \u0628\u0627\u0634\u062F)." },
      { id: "autism.d", group: "D", textFa: "\u0646\u0634\u0627\u0646\u0647\u200C\u0647\u0627 \u0639\u0645\u0644\u06A9\u0631\u062F \u0631\u0648\u0632\u0627\u0646\u0647 \u0631\u0627 \u0645\u0644\u0645\u0648\u0633 \u0645\u062E\u062A\u0644 \u06A9\u0631\u062F\u0647\u200C\u0627\u0646\u062F." },
      { id: "autism.e", group: "E", textFa: "\u0628\u0647\u062A\u0631 \u0628\u0627 \u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u0641\u06A9\u0631\u06CC \u06CC\u0627 \u0627\u062E\u062A\u0644\u0627\u0644 \u0632\u0628\u0627\u0646\u06CC \u0628\u0647\u200C\u062A\u0646\u0647\u0627\u06CC\u06CC \u062A\u0648\u0636\u06CC\u062D \u062F\u0627\u062F\u0647 \u0646\u0634\u0648\u062F." }
