      { id: "speech.b", group: "B", textFa: "\u062A\u0648\u0627\u0646\u0627\u06CC\u06CC \u06A9\u0645 \u0627\u0632 \u0627\u0646\u062A\u0638\u0627\u0631 \u0633\u0646 \u0648 \u0641\u0631\u0635\u062A \u0622\u0645\u0648\u0632\u0634 \u0627\u0633\u062A \u0648 \u0628\u0627 \u0645\u0648\u0642\u0639\u06CC\u062A \u0645\u062D\u062F\u0648\u062F \u0646\u0645\u06CC\u200C\u0634\u0648\u062F." },
      { id: "speech.c", group: "C", textFa: "\u0634\u0631\u0648\u0639 \u062F\u0631 \u062F\u0648\u0631\u0647\u0654 \u0627\u0628\u062A\u062F\u0627\u06CC\u06CC \u0631\u0634\u062F." },
      { id: "speech.d", group: "D", textFa: "\u062F\u0634\u0648\u0627\u0631\u06CC\u060C \u0639\u0645\u0644\u06A9\u0631\u062F \u0627\u0631\u062A\u0628\u0627\u0637\u06CC \u0648 \u0627\u062C\u062A\u0645\u0627\u0639\u06CC/\u062A\u062D\u0635\u06CC\u0644\u06CC \u0631\u0627 \u0645\u062E\u062A\u0644 \u06A9\u0631\u062F\u0647 \u0627\u0633\u062A." },
      { id: "speech.e", group: "E", textFa: "\u0628\u0647\u062A\u0631 \u0628\u0627 \u0645\u0634\u06A9\u0644 \u062D\u0633\u06CC (\u06A9\u0645\u200C\u0634\u0646\u0648\u0627\u06CC\u06CC)\u060C \u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u062D\u0631\u06A9\u062A\u06CC \u06AF\u0641\u062A\u0627\u0631 \u06CC\u0627 \u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u0641\u06A9\u0631\u06CC \u062A\u0648\u0636\u06CC\u062D \u062F\u0627\u062F\u0647 \u0646\u0634\u0648\u062F." }
