    differentials: ["\u0627\u0636\u0637\u0631\u0627\u0628 \u0641\u0631\u0627\u06AF\u06CC\u0631 (SCARED \u2014 \u0627\u06AF\u0631 \u062E\u0627\u0631\u062C \u0627\u0632 \u0627\u0645\u062A\u062D\u0627\u0646 \u0647\u0645 \u0647\u0633\u062A)"],
