// src/domain/clinical-engine/progress.ts
var PATH_PROBE_DEFAULT_THRESHOLD = 80;
var PATH_PROBE_MASTERY_STREAK = 2;
function olsSlopeOf(values) {
  const n = values.length;
  if (n < 2) return 0;
  const mx = (n - 1) / 2;
  const my = values.reduce((a, b) => a + b, 0) / n;
  let numr = 0;
  let den = 0;
  for (let i = 0; i < n; i++) {
    numr += (i - mx) * (values[i] - my);
    den += (i - mx) * (i - mx);
  }
  return den ? numr / den : 0;
}
__name(olsSlopeOf, "olsSlopeOf");
function masteryOf(series, threshold = PATH_PROBE_DEFAULT_THRESHOLD, streakNeeded = PATH_PROBE_MASTERY_STREAK) {
  let streak = 0;
  for (let i = series.length - 1; i >= 0; i--) {
    if (series[i].value >= threshold) streak += 1;
    else break;
  }
  if (streak >= streakNeeded) {
    const sinceIdx = series.length - streakNeeded;
    return { achieved: true, threshold, streak, sinceAt: series[sinceIdx].takenAt };
  }
  return { achieved: false, threshold, streak, sinceAt: null };
}
